/**
 * Calculate the Levenshtein distance between two strings.
 * @param {string} a - First string
 * @param {string} b - Second string
 * @returns {number} The Levenshtein distance
 */
function levenshteinDistance(a, b) {
  const alen = a.length;
  const blen = b.length;

  // Create a matrix to store distances
  const matrix = [];

  // Initialize first column
  for (let i = 0; i <= alen; i++) {
    matrix[i] = [i];
  }

  // Initialize first row
  for (let j = 0; j <= blen; j++) {
    matrix[0][j] = j;
  }

  // Fill in the rest of the matrix
  for (let i = 1; i <= alen; i++) {
    for (let j = 1; j <= blen; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,      // deletion
        matrix[i][j - 1] + 1,      // insertion
        matrix[i - 1][j - 1] + cost // substitution
      );
    }
  }

  return matrix[alen][blen];
}

/**
 * Find the closest matching property name using Levenshtein distance.
 * @param {string} missingProperty - The property name that was not found
 * @param {string[]} availableProperties - List of available property names
 * @param {number} maxDistance - Maximum Levenshtein distance for a suggestion
 * @returns {string|null} The closest matching property name or null
 */
function findClosestMatch(missingProperty, availableProperties, maxDistance) {
  let bestMatch = null;
  let bestDistance = maxDistance + 1;

  for (const prop of availableProperties) {
    const dist = levenshteinDistance(missingProperty, prop);
    if (dist <= maxDistance) {
      if (
        dist < bestDistance ||
        (dist === bestDistance && prop < bestMatch)
      ) {
        bestDistance = dist;
        bestMatch = prop;
      }
    }
  }

  return bestMatch;
}

/**
 * Create a debug helper object for a KnockoutJS ViewModel.
 * @param {Object} viewModel - A plain JavaScript object with properties
 * @returns {Object} A debug helper with diagnoseMissingProperty method
 */
function createDebugHelper(viewModel) {
  const availableProperties = Object.keys(viewModel || {}).sort();

  return {
    /**
     * Diagnose a missing property in a KnockoutJS binding.
     * @param {string} propertyName - The name of the property that failed to bind
     * @returns {Object} Diagnostic result object
     */
    diagnoseMissingProperty: function (propertyName) {
      const suggestion = findClosestMatch(propertyName, availableProperties, 3);

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties.slice(), // Return a copy
        suggestion: suggestion
      };
    }
  };
}

module.exports = {
  createDebugHelper: createDebugHelper,
  levenshteinDistance: levenshteinDistance,
  findClosestMatch: findClosestMatch
};"}

