/**
 * Test script for KnockoutJS Template Binding Error Debugger
 */

const { createDebugHelper } = require('./ko-debug');

// Define a sample ViewModel with properties
const viewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 0
};

// Create the debug helper
const debugHelper = createDebugHelper(viewModel);

// Get available properties for reference
const availableProps = debugHelper.diagnoseMissingProperty('').availableProperties;

/**
 * Run a single test case
 * @param {string} propertyName - The property name to diagnose
 * @param {string|null} expectedSuggestion - The expected suggestion
 * @param {string} description - Test description
 */
function runTest(propertyName, expectedSuggestion, description) {
  const result = debugHelper.diagnoseMissingProperty(propertyName);

  const passed = result.suggestion === expectedSuggestion &&
                 result.error === true &&
                 result.missingProperty === propertyName;

  const status = passed ? 'PASS' : 'FAIL';
  console.log(`${status}: ${description}`);

  if (!passed) {
    console.log(`  Expected suggestion: ${expectedSuggestion}`);
    console.log(`  Got suggestion: ${result.suggestion}`);
    console.log(`  Full result: ${JSON.stringify(result, null, 2)}`);
  }

  return passed;
}

// Test 1: Diagnose missing property "item" (should suggest "items")
const test1 = runTest('item', 'items', 'Diagnose missing property "item" should suggest "items"');

// Test 2: Diagnose missing property "selctedItem" (should suggest "selectedItem")
const test2 = runTest('selctedItem', 'selectedItem', 'Diagnose missing property "selctedItem" should suggest "selectedItem"');

// Test 3: Diagnose missing property "completelyWrong" (should have null suggestion)
const test3 = runTest('completelyWrong', null, 'Diagnose missing property "completelyWrong" should have null suggestion');

// Test 4: Diagnose missing property "isLoad" (should suggest "isLoading")
const test4 = runTest('isLoad', 'isLoading', 'Diagnose missing property "isLoad" should suggest "isLoading"');

// Summary
console.log('\n--- Summary ---');
const allPassed = test1 && test2 && test3 && test4;
if (allPassed) {
  console.log('All tests PASSED!');
  process.exit(0);
} else {
  console.log('Some tests FAILED!');
  process.exit(1);
}
JTESTEOF"}

